{
  "name": "pulsecloud-mcp",
  "version": "1.0.30",
  "description": "MCP server for PulseCloud hosting platform - manage Pterodactyl servers, Nginx Proxy Manager, Cloudflare DNS, and more via AI agents",
  "type": "module",
  "main": "dist/index.js",
  "bin": {
    "pulsecloud-mcp": "dist/index.js"
  },
  "files": [
    "dist"
  ],
  "scripts": {
    "start": "node dist/index.js",
    "dev": "npx tsx watch src/index.ts",
    "build": "npx tsc"
  },
  "keywords": [
    "mcp",
    "pulsecloud",
    "pterodactyl",
    "hosting",
    "nginx-proxy-manager",
    "cloudflare",
    "modelcontextprotocol",
    "opencode"
  ],
  "repository": {
    "type": "git",
    "url": "https://github.com/andradelima2/pulsecloud-mcp.git"
  },
  "author": "Fabricio Andrade Lima",
  "license": "MIT",
  "dependencies": {
    "@modelcontextprotocol/sdk": "^1.11.0",
    "ws": "^8.21.0",
    "zod": "^3.24.4"
  },
  "devDependencies": {
    "@types/node": "^22.15.3",
    "@types/ws": "^8.18.1",
    "tsx": "^4.19.4",
    "typescript": "^5.8.3"
  }
}
